%dw 2.0
output application/json
---
{
  code: "200",
  message: vars.rsLisim.cause default vars.rsLisim.message default "validacion exitosa",
  result: {}
}

%dw 2.0
output application/json
---
{
	"DocumentType": vars.initialPayload.documentType match {
		case "CC"  -> 1
        case "CE" -> 2
        else   -> "Invalid input"
	},
	"DocumentNumber": vars.initialPayload.documentNumber,
	"DateExpedition": (vars.initialPayload.dateExpedition as Date) as String {
		format: "yyyy-MM-dd"
	},
	"Surname": vars.initialPayload.firstLastName,
	"Cellphone": vars.initialPayload.cellphone,
	"Adviser": vars.initialPayload.adviser,
	"Channel": vars.initialPayload.channel,
	"Provider": vars.initialPayload.provider,
	"Portal": vars.initialPayload.portal
}
